function testKgFor() {
  const harvestsData = [["2027-04-18", "B2", "Radish", 1.2, "x"], ["2027-05-13", "B4", "Spinach", 2.4, "x"], ["2027-05-21", "B2", "Lettuce", 2.5, "x"]]
  console.log(KGFOR("B2", harvestsData))
}

function KGFOR(bedId, harvestsData) {
  let total = 0
  for (let i = 0; i < harvestsData.length; i++) {
    if (harvestsData[i][1] === bedId) {
      total += harvestsData[i][3]
    }
  }
  return Math.round(total * 10) / 10
}
